/* =====================================================================
   PSU-LASC — แจ้งทีมสัตวแพทย์ทาง LINE + อีเมล
   รับเหตุการณ์จากระบบรายงานฯ (มีแค่เลขอ้างอิง) → อ่านข้อมูลจริงจาก Firebase → ส่ง LINE ทันที
   และส่งรายการอีเมลต่อให้โหนด "ส่งอีเมล" (SMTP)

   Environment variables บนเซิร์ฟเวอร์ n8n
     LASC_FB_DB_URL     https://<project>-default-rtdb.<region>.firebasedatabase.app
     LASC_FB_DB_SECRET  Database secret (Project settings → Service accounts → Database secrets)
     LASC_FB_ROOT       animalReport (โปรเจกต์แยก) หรือ data/animalReport (โปรเจกต์ใช้ร่วม)
     LASC_ALERT_KEY     รหัสเชื่อมต่อ ต้องตรงกับช่อง「รหัสเชื่อมต่อ」ในระบบ
     LASC_LINE_TOKEN    Channel access token (long-lived) ของ LINE Messaging API
     LASC_APP_URL       ที่อยู่ระบบรายงานฯ เช่น https://lasc.psu.ac.th/animal-report/
   ===================================================================== */
/* ── ถ้า n8n อ่าน Environment variables ไม่ได้ (เช่น n8n Cloud) ให้กรอกค่าตรงนี้แทน ──
   กรอกที่นี่ที่เดียว ใช้ได้ทั้ง workflow นี้ · ค่าที่ตั้งไว้ใน $env จะถูกใช้ก่อนเสมอ      */
const CFG = {
  LASC_FB_DB_URL:    '',   /* เช่น https://psu-lasc-animal-report-default-rtdb.asia-southeast1.firebasedatabase.app */
  LASC_FB_DB_SECRET: '',   /* Database secret ของ Firebase — เป็นความลับ */
  LASC_FB_ROOT:      'animalReport',
  LASC_ALERT_KEY:    '',   /* รหัสเชื่อมต่อ ให้ตรงกับช่องในระบบรายงานฯ */
  LASC_LINE_TOKEN:   '',   /* Channel access token ของ LINE Messaging API */
  LASC_APP_URL:      ''    /* เช่น https://kwanchanokd.github.io/psu-lasc-animal-report/ */
};
const envv = (k) => {
  try { if (typeof $env !== 'undefined' && $env[k]) return String($env[k]); } catch (e) {}
  return String(CFG[k] || '');
};
const ENV = {
  db:     envv('LASC_FB_DB_URL').replace(/\/+$/, ''),
  secret: envv('LASC_FB_DB_SECRET'),
  root:   (envv('LASC_FB_ROOT') || 'animalReport').replace(/^\/+|\/+$/g, ''),
  key:    envv('LASC_ALERT_KEY'),
  line:   envv('LASC_LINE_TOKEN'),
  app:    envv('LASC_APP_URL')
};
const MAX_GUEST_PER_10MIN = 10;          /* กันการแจ้งซ้ำ ๆ จากผู้แจ้งทั่วไป */
const MAX_AGE_MIN = 30;                  /* แจ้งเตือนเฉพาะเรื่องที่เพิ่งบันทึก */

const errors = [];
const emails = [];
let lineSent = 0;

function finish(ok, extra) {
  const summary = Object.assign({ ok: ok, line: lineSent, email: emails.length, error: '', skipped: '' }, extra || {});
  if (errors.length && !summary.error) summary.error = errors.join(' · ');
  if (!emails.length) return [{ json: Object.assign({ to: '' }, summary) }];
  return emails.map(m => ({ json: Object.assign({}, summary, m) }));
}

/* ---------- อ่านคำขอ ---------- */
const body = $input.first().json.body || {};
let p = body.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { p = null; } }
if (!p && body && typeof body === 'object' && body.event) p = body;
if (!p || typeof p !== 'object') return finish(false, { error: 'bad payload' });
if (!ENV.db || !ENV.secret || !ENV.key) return finish(false, { error: 'n8n ยังตั้งค่า LASC_FB_DB_URL / LASC_FB_DB_SECRET / LASC_ALERT_KEY ไม่ครบ' });
if (p.key !== ENV.key) return finish(false, { error: 'รหัสเชื่อมต่อไม่ถูกต้อง' });

const ID = /^[A-Za-z0-9_-]{1,64}$/;
const event = String(p.event || '');
if (!/^(alert|status|test|register|member)$/.test(event)) return finish(false, { error: 'unknown event' });

/* ---------- Firebase REST ---------- */
const http = (opts) => this.helpers.httpRequest(Object.assign({ json: true, timeout: 15000 }, opts));
const fbUrl = (path) => `${ENV.db}/${ENV.root}/${path}.json?auth=${encodeURIComponent(ENV.secret)}`;
const fbGet = (path) => http({ method: 'GET', url: fbUrl(path) });
const fbPut = (path, v) => http({ method: 'PUT', url: fbUrl(path), body: v });
const logKey = (s) => String(s).replace(/[.#$\[\]\/]/g, '_');
async function once(key) {                /* true = ยังไม่เคยส่ง → จองไว้เลย */
  const k = logKey(key);
  const hit = await fbGet('notifyLog/' + k);
  if (hit) return false;
  await fbPut('notifyLog/' + k, { at: new Date().toISOString() });
  return true;
}

/* ---------- ข้อความ ---------- */
const TYPE = { emergency: '🚨 เหตุฉุกเฉิน', health: '🩺 ปัญหาสุขภาพสัตว์ทดลอง' };
const URG = { critical: '🔴 วิกฤต', urgent: '🟠 เร่งด่วน', routine: '🔵 ทั่วไป' };
const STAT = { new: '🆕 รอรับเรื่อง', ack: '📥 รับเรื่องแล้ว', treating: '💉 กำลังดูแลรักษา', closed: '✅ ปิดเรื่องแล้ว' };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const list = (v) => Array.isArray(v) ? v : (v && typeof v === 'object' ? Object.values(v) : []);
const link = ENV.app ? ENV.app.replace(/\/?$/, '/') + 'index.html?tab=alert' : '';
function rows(a) {
  return [
    ['เลขที่', a.docNo], ['ประเภท', TYPE[a.type]], ['ความเร่งด่วน', URG[a.urgency]],
    ['ลักษณะเหตุ', a.category], ['โครงการ', a.projectNo ? a.projectNo + ' ' + (a.projectName || '') : ''],
    ['สถานที่', a.location], ['กรง / รหัสสัตว์', a.cage],
    ['สัตว์', [a.species, a.sex, a.strain].filter(Boolean).join(' · ') + (a.qty ? ` — ${a.qty} ตัว` : '')],
    ['อาการ', list(a.signs).join(', ')],
    ['เริ่มพบ', [a.onsetDate, a.onsetTime].filter(Boolean).join(' ')],
    ['รายละเอียด', a.detail], ['ทำไปแล้ว', a.firstAid], ['ต้องการ', a.request],
    ['ผู้แจ้ง', `${a.reporter || ''} โทร ${a.phone || '-'}${a.email ? ' · ' + a.email : ''}`]
  ].filter(r => r[1]);
}
function htmlTable(rs) {
  return '<table style="border-collapse:collapse;max-width:720px;font-family:Sarabun,Tahoma,sans-serif;font-size:14px">' +
    rs.map(([k, v]) => `<tr><th style="text-align:left;background:#f2f6fa;padding:6px 10px;border:1px solid #ccd;width:30%">${esc(k)}</th>` +
      `<td style="padding:6px 10px;border:1px solid #ccd">${esc(v).replace(/\n/g, '<br>')}</td></tr>`).join('') + '</table>';
}
function wrap(lead, inner) {
  return `<div style="font-family:Sarabun,Tahoma,sans-serif;font-size:14px;color:#111"><p>${lead}</p>${inner || ''}` +
    (link ? `<p>เปิดระบบ: <a href="${esc(link)}">${esc(link)}</a></p>` : '') +
    '<p style="color:#777;font-size:12px">ส่งอัตโนมัติจากระบบรายงานการปฏิบัติต่อสัตว์ทดลอง PSU:LASC</p></div>';
}
async function pushLine(to, text) {
  if (!ENV.line || !to) return;
  try {
    await http({
      method: 'POST', url: 'https://api.line.me/v2/bot/message/push',
      headers: { Authorization: 'Bearer ' + ENV.line },
      body: { to: to, messages: [{ type: 'text', text: String(text).slice(0, 4900) }] }
    });
    lineSent++;
  } catch (e) {
    errors.push('LINE ' + String(to).slice(0, 6) + '…: ' + ((e.response && e.response.body && e.response.body.message) || e.message || e));
  }
}
function mail(to, subject, html) {
  if (to && /@/.test(to)) emails.push({ to: String(to), subject: String(subject).slice(0, 240), html: html });
}
async function activeVets(filter) {
  const all = list(await fbGet('vets')).filter(v => v && v.active !== false);
  return all.filter(filter || (() => true));
}

/* ---------- เหตุการณ์ ---------- */
if (event === 'alert' || event === 'status') {
  const id = String(p.id || '');
  const guest = p.guest === true || p.guest === 'true';
  const uid = String(p.uid || '');
  if (!ID.test(id) || (!guest && !ID.test(uid))) return finish(false, { error: 'bad id' });
  const a = await fbGet(guest ? `guestAlerts/${id}` : `alerts/${uid}/${id}`);
  if (!a || a.id !== id) return finish(false, { error: 'ไม่พบเรื่องนี้ในฐานข้อมูล' });

  if (event === 'alert') {
    const age = (Date.now() - Date.parse(a.createdAt || 0)) / 60000;
    if (!(age >= -5 && age <= MAX_AGE_MIN)) return finish(true, { skipped: 'เรื่องเก่าเกิน ' + MAX_AGE_MIN + ' นาที' });
    if (guest) {
      const bucket = new Date(); bucket.setMinutes(Math.floor(bucket.getMinutes() / 10) * 10, 0, 0);
      const rk = 'guestRate/' + bucket.toISOString().slice(0, 16).replace(/[-:T]/g, '');
      const n = Number(((await fbGet('notifyLog/' + rk)) || {}).n || 0);
      if (n >= MAX_GUEST_PER_10MIN) return finish(true, { skipped: 'มีการแจ้งจากผู้แจ้งทั่วไปมากเกินไป — โปรดตรวจกล่องรับแจ้งในระบบ' });
      await fbPut('notifyLog/' + rk, { n: n + 1 });
    }
    if (!(await once('alert_' + id))) return finish(true, { skipped: 'แจ้งเรื่องนี้ไปแล้ว' });
    const level = ['critical', 'urgent', 'routine'].includes(a.urgency) ? a.urgency : 'critical';
    const vets = await activeVets(v => v[level] !== false);
    if (!vets.length) return finish(true, { skipped: 'ยังไม่มีสัตวแพทย์ในรายชื่อผู้รับแจ้ง' });
    const rs = rows(a);
    const text = `${URG[a.urgency] || ''} แจ้ง${(TYPE[a.type] || '').replace(/^\S+\s/, '')}\n` +
      rs.map(([k, v]) => `${k}: ${v}`).join('\n') +
      (guest ? '\n(ผู้แจ้งทั่วไป — ยังไม่ได้เป็นสมาชิกที่อนุมัติ)' : '') + (link ? `\n\nรับเรื่อง: ${link}` : '');
    const subject = `[LASC ${URG[a.urgency] || ''}] แจ้ง${(TYPE[a.type] || '').replace(/^\S+\s/, '')} — ${a.category || list(a.signs).slice(0, 2).join(', ') || a.species || ''} (${a.docNo})`;
    const html = wrap(`เรียน ทีมสัตวแพทย์ศูนย์สัตว์ทดลอง<br>มีการแจ้ง<b>${esc(TYPE[a.type] || '')}</b> ระดับ <b>${esc(URG[a.urgency] || '')}</b>` +
      (guest ? ' <i>(ผู้แจ้งทั่วไป)</i>' : ''), htmlTable(rs));
    for (const v of vets) { await pushLine(v.lineId, text); mail(v.email, subject, html); }
    return finish(true);
  }

  /* status: แจ้งความคืบหน้าในทีมทาง LINE + แจ้งผลถึงผู้แจ้งทางอีเมล */
  const h = list(a.history);
  if (!(await once(`status_${id}_${h.length}`))) return finish(true, { skipped: 'แจ้งความคืบหน้านี้ไปแล้ว' });
  const st = STAT[a.status] || a.status;
  const last = h[h.length - 1] || {};
  const vets = await activeVets(v => !!v.lineId);
  const t = `${st} — ${a.docNo}\n${a.species || ''} ${a.qty || ''} ตัว · ${a.location || ''}` +
    (a.vetName ? `\nผู้รับผิดชอบ: ${a.vetName}` : '') + (a.outcome && a.status === 'closed' ? `\nผล: ${a.outcome}` : '') +
    (last.note ? `\nบันทึก: ${last.note}` : '');
  for (const v of vets) await pushLine(v.lineId, t);
  if ((p.mail === true || p.mail === 'true') && a.email) {
    const lead = `เรียน ${esc(a.reporter || '')}<br>ทีมสัตวแพทย์ได้อัปเดตเรื่องที่ท่านแจ้ง (${esc(a.docNo)}) เป็น <b>${esc(st)}</b>` +
      (a.vetName ? ` — ผู้รับผิดชอบ: ${esc(a.vetName)}` : '') +
      (a.outcome && a.status === 'closed' ? `<br>ผลการดูแล: <b>${esc(a.outcome)}</b>` : '') +
      (a.vetNote ? `<br>บันทึก / คำแนะนำ: ${esc(a.vetNote).replace(/\n/g, '<br>')}` : '') +
      (/Euthanasia|Died/.test(a.outcome || '') && a.status === 'closed' ? '<br><b>กรุณาบันทึกรายงานการปฏิบัติต่อสัตว์ทดลองในระบบด้วย</b>' : '');
    mail(a.email, `[LASC] อัปเดตเรื่องที่แจ้ง ${a.docNo} — ${st.replace(/^\S+\s/, '')}`, wrap(lead, htmlTable(rows(a))));
  }
  return finish(true);
}

if (event === 'test') {
  const minute = new Date().toISOString().slice(0, 16).replace(/[-:T]/g, '');
  const vid = String(p.vetId || '');
  if (vid && !ID.test(vid)) return finish(false, { error: 'bad vetId' });
  if (!(await once(`test_${vid || 'all'}_${minute}`))) return finish(true, { skipped: 'ทดสอบไปแล้วในนาทีนี้ — รอสักครู่แล้วลองใหม่' });
  const vets = vid ? [await fbGet('vets/' + vid)].filter(Boolean) : await activeVets();
  if (!vets.length) return finish(true, { skipped: 'ไม่พบผู้รับแจ้ง' });
  for (const v of vets) {
    await pushLine(v.lineId, `🔔 ทดสอบการแจ้งเตือน PSU:LASC\nถึง: ${v.name || ''}\nช่องทางนี้พร้อมรับแจ้งเหตุฉุกเฉิน/ปัญหาสุขภาพสัตว์แล้ว`);
    mail(v.email, '[ทดสอบ] การแจ้งเตือนทีมสัตวแพทย์ PSU:LASC', wrap(`เรียน ${esc(v.name || '')}<br>ช่องทางอีเมลนี้พร้อมรับแจ้งเหตุฉุกเฉิน/ปัญหาสุขภาพสัตว์ทดลองแล้ว`));
  }
  return finish(true);
}

if (event === 'register') {
  const uid = String(p.uid || '');
  if (!ID.test(uid)) return finish(false, { error: 'bad uid' });
  const u = await fbGet('users/' + uid);
  if (!u) return finish(false, { error: 'ไม่พบข้อมูลลงทะเบียน' });
  if (await fbGet('members/' + uid)) return finish(true, { skipped: 'พิจารณาแล้ว' });
  if (!(await once('register_' + uid))) return finish(true, { skipped: 'แจ้งไปแล้ว' });
  const vets = await activeVets(v => v.notifyMembers === true);
  const text = `👥 มีนักวิจัยลงทะเบียนใหม่ รออนุมัติ\n${u.name || ''} · ${u.email || ''}\n${u.org || ''} ${u.phone || ''}` +
    (ENV.app ? `\n\nอนุมัติ: ${ENV.app.replace(/\/?$/, '/')}index.html?tab=members` : '');
  for (const v of vets) {
    await pushLine(v.lineId, text);
    mail(v.email, `[LASC] นักวิจัยลงทะเบียนใหม่ — ${u.name || u.email || ''}`, wrap(esc(text).replace(/\n/g, '<br>')));
  }
  return finish(true);
}

if (event === 'member') {
  const uid = String(p.uid || '');
  if (!ID.test(uid)) return finish(false, { error: 'bad uid' });
  const [u, m] = [await fbGet('users/' + uid), await fbGet('members/' + uid)];
  if (!u || !m || !m.status) return finish(false, { error: 'ไม่พบข้อมูล' });
  if (!(await once(`member_${uid}_${m.status}_${m.at || ''}`))) return finish(true, { skipped: 'แจ้งไปแล้ว' });
  const T = {
    approved: ['บัญชีของท่านได้รับอนุมัติแล้ว', 'ท่านเข้าสู่ระบบรายงานการปฏิบัติต่อสัตว์ทดลองได้ทันที รายงานที่บันทึกไว้ในเครื่องจะส่งขึ้นระบบกลางให้อัตโนมัติ'],
    rejected: ['บัญชีของท่านไม่ได้รับอนุมัติ', 'หากมีข้อสงสัย กรุณาติดต่อเจ้าหน้าที่ศูนย์สัตว์ทดลอง'],
    suspended: ['บัญชีของท่านถูกระงับการใช้งาน', 'กรุณาติดต่อเจ้าหน้าที่ศูนย์สัตว์ทดลอง']
  }[m.status];
  if (!T) return finish(true, { skipped: 'สถานะไม่ต้องแจ้ง' });
  mail(u.email, `[LASC] ${T[0]}`, wrap(`เรียน ${esc(u.name || '')}<br><b>${T[0]}</b><br>${T[1]}`));
  return finish(true);
}

return finish(false, { error: 'unhandled' });
